export default {"html":"<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"0\"><span class=\"line\"><span>This is the secret sauce. Let me know if you rewrite it more cleanly.</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"5\" class=\"code-line\">In Ionic, <code>Infinite Scroll</code> and <code>Refresher</code> load more content or reload it. With <code>Infinite Scroll</code> you often POST the current content ID and load only what follows; with <code>Refresher</code> you often clear existing items and reload. Depending on backend design—or when \"some content was deleted, so I want to merge with what is already loaded\"—you also get cases like this:</p>\n<ul data-line=\"7\" class=\"code-line\">\n<li data-line=\"7\" class=\"code-line\">Like counts on a timeline may have changed, so I want to keep overwriting at least the latest 15 items</li>\n<li data-line=\"8\" class=\"code-line\">Some arrays may have been deleted, so I want to overwrite and reflect deletions</li>\n<li data-line=\"9\" class=\"code-line\">The update date changed, so I want to remove the old matching entry and bring in the latest</li>\n</ul>\n<p data-line=\"11\" class=\"code-line\">Merging associative arrays gets requirement-heavy once you think it through—\"sort by ID, but for the same ID sort by created time ascending,\" and so on.<br>\nThis has become something of a secret sauce for me, so I am publishing the associative-array merge method I built for my needs.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span> public ArrayConcatById&lt;T&gt;(</span></span>\n<span class=\"line\"><span>    arrayOld: T[],</span></span>\n<span class=\"line\"><span>    arrayNew: T[],</span></span>\n<span class=\"line\"><span>    key: string,</span></span>\n<span class=\"line\"><span>    order: string = 'DESC',</span></span>\n<span class=\"line\"><span>    secondaryKey: string = null,</span></span>\n<span class=\"line\"><span>  ): T[] {</span></span>\n<span class=\"line\"><span>    if (!arrayNew.length &amp;&amp; !arrayOld.length) {</span></span>\n<span class=\"line\"><span>      return [];</span></span>\n<span class=\"line\"><span>    }</span></span>\n<span class=\"line\"><span>    const lead = arrayNew[0][key] as number;</span></span>\n<span class=\"line\"><span>    const last = arrayNew[arrayNew.length - 1][key] as number;</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    arrayOld = arrayOld || [];</span></span>\n<span class=\"line\"><span>    arrayNew = arrayNew || [];</span></span>\n<span class=\"line\"><span>    arrayOld = arrayOld.filter((vol) =&gt; {</span></span>\n<span class=\"line\"><span>      return (</span></span>\n<span class=\"line\"><span>        (lead &gt; last &amp;&amp; ((vol[key] as number) &gt;= lead || (vol[key] as number) &lt;= last)) ||</span></span>\n<span class=\"line\"><span>        (lead &lt; last &amp;&amp; ((vol[key] as number) &lt;= lead || (vol[key] as number) &gt;= last)) ||</span></span>\n<span class=\"line\"><span>        (lead as number) === (last as number)</span></span>\n<span class=\"line\"><span>      );</span></span>\n<span class=\"line\"><span>    });</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    let old: T[];</span></span>\n<span class=\"line\"><span>    if (secondaryKey !== null) {</span></span>\n<span class=\"line\"><span>      old = arrayOld.filter((vol) =&gt; {</span></span>\n<span class=\"line\"><span>        let flg = true;</span></span>\n<span class=\"line\"><span>        arrayNew.forEach((element) =&gt; {</span></span>\n<span class=\"line\"><span>          if (element[secondaryKey] === vol[secondaryKey]) {</span></span>\n<span class=\"line\"><span>            flg = false;</span></span>\n<span class=\"line\"><span>          }</span></span>\n<span class=\"line\"><span>        });</span></span>\n<span class=\"line\"><span>        return flg;</span></span>\n<span class=\"line\"><span>      });</span></span>\n<span class=\"line\"><span>    } else {</span></span>\n<span class=\"line\"><span>      old = arrayOld;</span></span>\n<span class=\"line\"><span>    }</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    const oldData = old.filter((vol) =&gt; {</span></span>\n<span class=\"line\"><span>      let flg = true;</span></span>\n<span class=\"line\"><span>      arrayNew.forEach((element) =&gt; {</span></span>\n<span class=\"line\"><span>        if (element[key] === vol[key]) {</span></span>\n<span class=\"line\"><span>          flg = false;</span></span>\n<span class=\"line\"><span>        }</span></span>\n<span class=\"line\"><span>      });</span></span>\n<span class=\"line\"><span>      return flg;</span></span>\n<span class=\"line\"><span>    });</span></span>\n<span class=\"line\"><span>    let data = arrayNew.concat(oldData);</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    // Default is descending (DESC)</span></span>\n<span class=\"line\"><span>    let ord = -1;</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    if (order === 'ASC') {</span></span>\n<span class=\"line\"><span>      // Ascending (ASC) when specified</span></span>\n<span class=\"line\"><span>      console.log('ASC');</span></span>\n<span class=\"line\"><span>      ord = 1;</span></span>\n<span class=\"line\"><span>    }</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    data = data.sort((a, b) =&gt; {</span></span>\n<span class=\"line\"><span>      const x = a[key] as number;</span></span>\n<span class=\"line\"><span>      const y = b[key] as number;</span></span>\n<span class=\"line\"><span>      if (x &gt; y) {</span></span>\n<span class=\"line\"><span>        return ord;</span></span>\n<span class=\"line\"><span>      }</span></span>\n<span class=\"line\"><span>      if (x &lt; y) {</span></span>\n<span class=\"line\"><span>        return ord * -1;</span></span>\n<span class=\"line\"><span>      }</span></span>\n<span class=\"line\"><span>      return 0;</span></span>\n<span class=\"line\"><span>    });</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span>    return data;</span></span>\n<span class=\"line\"><span>  }</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"90\" class=\"code-line\">Use it as a helper like this. The sort ID must be numeric.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"92\"><span class=\"line\"><span>this.items = this.helper.ArrayConcatById&lt;Interface&gt;(this.items, newItems, 'id', 'ASC');</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"97\" class=\"code-line\">If <code>concat</code> does not meet your array-merge needs, give it a try. If you refactor it into something cleaner, please tell me quietly. Actually, looking at it again after a long time, I want to rewrite this...</p>\n<p data-line=\"99\" class=\"code-line\">See you again.</p>\n","headings":[]} as const;
